import sys
from collections import deque

def main():
    stream = sys.stdin.readline().strip()

    if not stream:
        print()
        return

    count = {}
    queue = deque()
    result = []

    for ch in stream:
        count[ch] = count.get(ch, 0) + 1

        if count[ch] == 1:
            queue.append(ch)

        while queue and count[queue[0]] > 1:
            queue.popleft()

        if queue:
            result.append(queue[0])
        else:
            result.append(-1)

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
